create or replace function command_boundary.normalize_chat_body(body text) returns text
language sql immutable strict set search_path = '' as $normalize$
  select replace(replace(body, E'\r\n', E'\n'), E'\r', E'\n');
$normalize$;

-- Raw code-point adapter permits conformance testing U+0000, which PostgreSQL
-- text cannot represent. Production callers enter via chat_visual_length.
create or replace function command_boundary.chat_grapheme_length(points integer[]) returns integer
language plpgsql immutable strict set search_path = '' as $length$
declare
  cp integer;
  property integer;
  current_class integer;
  previous_class integer := 0;
  indic integer;
  pictograph boolean;
  regional_indicators integer := 0;
  conjunct integer := 0;
  pictograph_extend boolean := false;
  pictograph_zwj boolean := false;
  attach boolean;
  result integer := 0;
begin
  foreach cp in array points loop
    property := command_boundary.chat_unicode_property(cp);
    current_class := property & 15;
    indic := (property >> 4) & 3;
    pictograph := (property & 64) <> 0;
    attach := false;
    if result > 0 then
      if previous_class = 1 and current_class = 2 then attach := true; -- GB3
      elsif previous_class between 1 and 3 or current_class between 1 and 3 then attach := false; -- GB4/5
      elsif previous_class = 9 and current_class in (9,10,12,13) then attach := true; -- GB6
      elsif previous_class in (12,10) and current_class in (10,11) then attach := true; -- GB7
      elsif previous_class in (13,11) and current_class = 11 then attach := true; -- GB8
      elsif current_class in (4,5,8) then attach := true; -- GB9/9a
      elsif previous_class = 7 then attach := true; -- GB9b
      elsif indic = 1 and conjunct = 2 then attach := true; -- GB9c
      elsif pictograph and pictograph_zwj then attach := true; -- GB11
      elsif previous_class = 6 and current_class = 6 and regional_indicators % 2 = 1 then attach := true; -- GB12/13
      end if;
    end if;
    if not attach then result := result + 1; end if;
    if indic = 1 then conjunct := 1;
    elsif indic = 2 and conjunct > 0 then conjunct := 2;
    elsif indic <> 3 then conjunct := 0;
    end if;
    pictograph_zwj := current_class = 5 and pictograph_extend;
    pictograph_extend := pictograph or (current_class = 4 and pictograph_extend);
    if current_class = 6 then regional_indicators := regional_indicators + 1;
    else regional_indicators := 0;
    end if;
    previous_class := current_class;
  end loop;
  return result;
end;
$length$;

create or replace function command_boundary.chat_visual_length(body text) returns integer
language sql immutable strict set search_path = '' as $adapter$
  select command_boundary.chat_grapheme_length(coalesce(array_agg(ascii(ch) order by ord), '{}'::integer[]))
  from regexp_split_to_table(command_boundary.normalize_chat_body(body), '') with ordinality p(ch, ord)
  where ch <> '';
$adapter$;

create or replace function command_boundary.validate_chat_body(body text, image_count integer) returns text
language plpgsql immutable set search_path = '' as $validate$
declare
  normalized text;
begin
  if body is null then
    raise exception using errcode = '22023', message = 'Body must be a string.';
  end if;
  if image_count is null or image_count < 0 or image_count > 4 then
    raise exception using errcode = '22023', message = 'Image count must be an integer between 0 and 4.';
  end if;
  normalized := command_boundary.normalize_chat_body(body);
  if command_boundary.chat_visual_length(normalized) > 10000 then
    raise exception using errcode = '22023', message = 'Body must be 10000 visual characters or fewer.';
  end if;
  if image_count = 0 and not exists (
    select 1 from regexp_split_to_table(normalized, '') ch
    where ch <> '' and (command_boundary.chat_unicode_property(ascii(ch)) & 128) = 0
  ) then
    raise exception using errcode = '22023', message = 'Body must not be blank without an image.';
  end if;
  return normalized;
end;
$validate$;

revoke all on function command_boundary.chat_unicode_property(integer) from public, anon, authenticated, service_role;
revoke all on function command_boundary.normalize_chat_body(text) from public, anon, authenticated, service_role;
revoke all on function command_boundary.chat_grapheme_length(integer[]) from public, anon, authenticated, service_role;
revoke all on function command_boundary.chat_visual_length(text) from public, anon, authenticated, service_role;
revoke all on function command_boundary.validate_chat_body(text, integer) from public, anon, authenticated, service_role;

commit;
